const now = new Date();
const weekStart = new Date(now);
weekStart.setDate(now.getDate() - now.getDay() + 1);

return {
  bruno: {
    phone: '5561991963278',
    name: 'Bruno'
  },
  search: {
    location: 'Brasilia, DF, Brasil',
    lat: -15.7939,
    lng: -47.8828,
    radius: 15000,
    types: 'beauty_salon|hair_care|barber|spa|tattoo_parlor',
    numResults: 5
  },
  weekOf: weekStart.toLocaleDateString('pt-BR'),
  dryRun: process.env.PROSPECTING_DRY_RUN === 'true'
};

const serpResult = $input.first().json;
const config = $('Code - Config Prospeccao').first().json;
const rawPlaces = serpResult.local_results || [];

const typeLabels = {
  'beauty_salon': 'Salao de Beleza',
  'hair_care': 'Cabeleireiro',
  'barber': 'Barbearia',
  'spa': 'Spa',
  'tattoo_parlor': 'Estudio de Tatuagem'
};

const prospects = [];
const seen = new Set();

for (const place of rawPlaces) {
  if (prospects.length >= config.search.numResults) break;

  const phone = (place.phone || '').replace(/\D/g, '');
  if (!phone || phone.length < 10) continue;

  const key = place.title + '|' + phone;
  if (seen.has(key)) continue;
  seen.add(key);

  const types = place.types || [];
  let tipo = 'Negocio Local';
  for (const t of types) {
    if (typeLabels[t]) {
      tipo = typeLabels[t];
      break;
    }
  }

  const normalizedPhone = phone.startsWith('55') ? phone : '55' + phone;

  prospects.push({
    json: {
      nome: place.title,
      endereco: place.address || 'N/A',
      telefone: normalizedPhone,
      tipo: tipo,
      rating: place.rating || 'N/A',
      reviews: place.reviews || 0
    }
  });
}

if (prospects.length === 0) {
  prospects.push({
    json: {
      nome: 'Nenhum prospect encontrado',
      endereco: '-',
      telefone: '-',
      tipo: '-',
      rating: '-',
      reviews: 0
    }
  });
}

return prospects;

const config = $('Code - Config Prospeccao').first().json;
const prospects = $input.all();

let message = `*Prospeccao semanal backe.co*\n`;
message += `Semana de ${config.weekOf}\n\n`;
message += `${prospects.length} possiveis clientes p/ automacao WhatsApp:\n\n`;

prospects.forEach((p, i) => {
  const d = p.json;
  message += `${i + 1}. *${d.nome}*\n`;
  message += `   Endereco: ${d.endereco}\n`;
  message += `   Telefone: ${d.telefone}\n`;
  message += `   Tipo: ${d.tipo}\n`;
  if (d.rating !== 'N/A') {
    message += `   Avaliacao: ${d.rating} (${d.reviews} reviews)\n`;
  }
  message += `\n`;
});

message += `_Gerado automaticamente pelo workflow n8n_`;

return [{
  json: {
    brunoPhone: config.bruno.phone,
    message: message,
    prospectCount: prospects.length,
    weekOf: config.weekOf,
    dryRun: config.dryRun
  }
}];

const result = $input.first().json;

return [{
  json: {
    status: result.dryRun ? 'dry_run' : 'sent',
    prospectCount: result.prospectCount,
    weekOf: result.weekOf,
    timestamp: new Date().toISOString()
  }
}];
